use crate::model::{Summary,Job};

pub fn run(jobs:&[Job], budget:i64)->Summary {
    let mut completed = vec![false; jobs.len()];
    let mut order = Vec::new();
    let mut spent = 0;
    let mut remaining = budget;

    loop {
        let mut selected: Option<usize> = None;
        for (index, job) in jobs.iter().enumerate() {
            if completed[job.id as usize] || job.cost > remaining {
                continue;
            }
            if job.deps.iter().any(|dependency| !completed[*dependency as usize]) {
                continue;
            }
            if selected.is_none_or(|current| job.id < jobs[current].id) {
                selected = Some(index);
            }
        }

        let Some(index) = selected else { break };
        let job = &jobs[index];
        completed[job.id as usize] = true;
        order.push(job.id);
        spent += job.cost;
        remaining -= job.cost;
    }

    Summary {
        blocked: (jobs.len() - order.len()) as i64,
        order,
        spent,
    }
}

